    self._image.gameObject:SetActive(true)
    local resource = self._resourceMaster.ResourceList:FirstOrDefault(function(r) return r.FileName == nakami.ImageId end)
    if resource == nil then
      Debug.Log(CONCAT("ImageIDが見つからず", nakami.ImageId))
      self._image.gameObject:SetActive(false)
    else
      Debug.Log(CONCAT("ImageID=", nakami.ImageId))
      Settings:addImage(nakami.ImageId, true)
      local image = self._image
      image.sprite = LoadPictures.LoadPictureAsync(resource.FileName, "JINE")
      self._imageFileName = resource.FileName
      local size = self._image:GetComponent("RectTransform").rect.size
      self._image.size = size
      self._image:GetComponent("BoxCollider2D").size = size
      local component = self._image.gameObject:GetComponent("Button")
      component:OnClickAsObservable():Subscribe(function(_)
        spawn(function() ImageViewerHelper.OpenImageViewer(resource.FileName) end)
      end):AddTo(component.gameObject)
      if self.imageOverHungObject ~= nil then
        self.imageOverHungObject:SetParentRect(self.transform.parent.parent:GetComponent("RectTransform"))
      end
    end
  end
  self:SetBody(nakami)
  self:SetLocalize(nakami)
  if nakami.JineUserType == "pi" and kidokMilliSecond == 1 then
    self:OnKidoku(1000)
  end
  self:SetLayout(nakami)
  self.cellalpha:DOFade_1(0.4, 1)
  if nakami.JineUserType == "pi" and kidokMilliSecond > 1 then
    Observable.Timer(TimeSpan.FromSeconds(IDIV(nakami.kidokumillisecond, 1000))):Subscribe(function(_)
      self:OnKidoku(1000)
    end):AddTo(self)
  end
end

